// Layer defaults
function defaultPlayVisualLayers() {
  return [
    { id: "sky", name: "Sky", role: "background", frame: -1, scale: 8, parallax: 0.04, y: 0, opacity: 1, repeatX: false, visible: true, fit: "cover" },
    { id: "far", name: "Far BG", role: "background", frame: -1, scale: 5, parallax: 0.16, y: 72, opacity: 0.72, repeatX: true, visible: true, fit: "tile" },
    { id: "mid", name: "Mid BG", role: "background", frame: -1, scale: 4, parallax: 0.38, y: 180, opacity: 0.9, repeatX: true, visible: true, fit: "tile" },
    { id: "front", name: "Foreground", role: "foreground", frame: -1, scale: 4, parallax: 0.82, y: 276, opacity: 1, repeatX: true, visible: true, fit: "tile" },
    { id: "overlay", name: "OVERLAY", role: "overlay", frame: -1, scale: 6, parallax: 0, y: 0, opacity: 1, repeatX: false, visible: false, fit: "cover" }
  ];
}
// Number clamp
function finiteNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}
function clampFiniteNumber(value, fallback, min, max) {
  return Math.max(min, Math.min(finiteNumber(value, fallback), max));
}

function clampPlayLayer(layer, index = 0) {
  const base = defaultPlayVisualLayers()[index] || defaultPlayVisualLayers()[0];
  const next = { ...base, ...(layer || {}) };
  next.name = next.name || base.name;
  next.role = ["background", "foreground", "overlay"].includes(next.role) ? next.role : base.role;
  if (next.role === "overlay") {
    next.name = "OVERLAY";
    next.repeatX = false;
    next.fit = "cover";
    next.parallax = 0;
  }
  next.frame = Number.isFinite(Number(next.frame)) ? Math.max(-1, Math.min(Number(next.frame), state.frames.length - 1)) : -1;
  next.scale = clampFiniteNumber(next.scale, base.scale, 0.5, 32);
  next.parallax = clampFiniteNumber(next.parallax, 0, -4, 4);
  next.y = clampFiniteNumber(next.y, 0, -1024, 2160);
  next.opacity = Math.max(0, Math.min(Number(next.opacity ?? 1), 1));
  next.repeatX = next.repeatX !== false;
  next.visible = next.visible !== false;
  next.fit = ["cover", "contain", "stretch", "tile"].includes(next.fit) ? next.fit : "tile";
  return next;
}

// Project data
function projectWidth(project = state) { return Math.max(1, Number(project.width) || Number(project.size) || 32); }
function projectHeight(project = state) { return Math.max(1, Number(project.height) || Number(project.size) || 32); }
function projectLabel(project = state) { return `${projectWidth(project)} × ${projectHeight(project)}`; }
function syncProjectSizeAlias(project = state) { project.width = projectWidth(project); project.height = projectHeight(project); project.size = Math.max(project.width, project.height); }
function makeDialogueCharacter(name = "Character", frame = 0, position = "left", role = "npc") {
  return { id: `char-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`, name, frame, position, role, scale: 3, flip: false, visible: true, startLine: 0 };
}
function defaultDialogueState() {
  const first = { id: "char-a", name: "Character A", frame: 0, position: "left", role: "actor", scale: 3, flip: false, visible: false, startLine: 0 };
  const second = { id: "char-b", name: "Character B", frame: 0, position: "right", role: "npc", scale: 3, flip: true, visible: true, startLine: 1 };
  return {
    enabled: false,
    currentLine: 0,
    typewriter: true,
    characters: [first, second],
    lines: [
      { characterId: first.id, speaker: first.name, text: "Hello! This is a test line.", frame: 0, nextLine: 1 },
      { characterId: second.id, speaker: second.name, text: "Swap frames and text to mock up a conversation.", frame: 0, nextLine: -1 }
    ]
  };
}

function playSceneId(value = "") {
  const clean = String(value || "").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48);
  return clean || `scene-${Date.now().toString(36)}`;
}
function normalizePlayAudioRecord(audio = {}) {
  const helper = window.PixelBugAudioStudio?.helpers;
  const source = String(audio.dataUrl || "");
  const maxChars = helper?.MAX_AUDIO_CHARS || 17 * 1024 * 1024;
  const withinBytes = helper?.dataUrlByteLength ? helper.dataUrlByteLength(source) <= (helper.MAX_FILE_BYTES || 12 * 1024 * 1024) : true;
  const dataUrl = /^data:audio\/(?:wav|wave|x-wav|mpeg|mp3|ogg|webm|mp4|x-m4a);base64,[a-z0-9+/=]+$/i.test(source) && source.length <= maxChars && withinBytes ? source : "";
  return { assetId: String(audio.assetId || "").replace(/[^a-z0-9_-]+/gi, "-").slice(0, 48), name: String(audio.name || "").slice(0, 120), dataUrl, volume: Math.max(0, Math.min(Number(audio.volume) || 0.7, 1)), loop: audio.loop !== false };
}
function normalizePlayAudioAsset(asset = {}, index = 0) {
  const helper = window.PixelBugAudioStudio?.helpers;
  if (helper?.normalizeAsset) return helper.normalizeAsset(asset, index);
  return { id: String(asset.id || `audio-${index + 1}`).replace(/[^a-z0-9_-]+/gi, "-").slice(0, 48), name: String(asset.name || `Audio ${index + 1}`).slice(0, 64), kind: asset.kind === "music" ? "music" : "sfx", dataUrl: /^data:audio\/(?:wav|wave|x-wav|mpeg|mp3|ogg|webm|mp4|x-m4a);base64,[a-z0-9+/=]+$/i.test(String(asset.dataUrl || "")) ? String(asset.dataUrl).slice(0, 17 * 1024 * 1024) : "", duration: Math.max(0, Math.min(Number(asset.duration) || 0, 600)), volume: Math.max(0, Math.min(Number(asset.volume) || 1, 1)), loop: asset.loop === true };
}
function playAudioAssetById(id) {
  return (state.playMode?.audioLibrary || []).find(asset => String(asset.id) === String(id)) || null;
}
function resolvedPlayAudio(audio = state.playMode?.audio) {
  const record = normalizePlayAudioRecord(audio || {});
  const asset = record.assetId ? playAudioAssetById(record.assetId) : null;
  return asset?.dataUrl ? { ...record, name: asset.name, dataUrl: asset.dataUrl, kind: asset.kind } : record;
}
function playAudioMixerVolume(kind = "music") {
  const mixer = state.playMode?.audioMixer || {};
  const master = Math.max(0, Math.min(Number(mixer.master) || 0, 1));
  if (kind === "music") return mixer.muteMusic === true ? 0 : master * Math.max(0, Math.min(Number(mixer.music) || 0, 1));
  return mixer.muteSfx === true ? 0 : master * Math.max(0, Math.min(Number(mixer.sfx) || 0, 1));
}
function playSceneSnapshot(source = state?.playMode || {}, id = "scene-main", name = "Scene 1") {
  return {
    id: playSceneId(id),
    name: String(name || "Scene").slice(0, 40),
    idleFrame: Number(source.idleFrame) || 0,
    walkFrame: Number(source.walkFrame) || 0,
    jumpFrame: Number(source.jumpFrame) || 0,
    sceneWidth: Number(source.sceneWidth) || 640,
    sceneHeight: Number(source.sceneHeight) || 360,
    worldWidth: Number(source.worldWidth) || 1600,
    groundY: Number(source.groundY) || 300,
    actorScale: Number(source.actorScale) || 3,
    backgroundFrame: Number.isFinite(Number(source.backgroundFrame)) ? Number(source.backgroundFrame) : -1,
    backgroundScale: source.backgroundScale || "cover",
    showGridOverlay: source.showGridOverlay !== false,
    cameraFollow: source.cameraFollow !== false,
    autoScroll: source.autoScroll === true,
    scrollSpeed: Number(source.scrollSpeed) || 1.25,
    sceneryFrame: Number.isFinite(Number(source.sceneryFrame)) ? Number(source.sceneryFrame) : -1,
    sceneryScale: Number(source.sceneryScale) || 3,
    scenerySpeed: Number(source.scenerySpeed) || 0.45,
    sceneryY: Number(source.sceneryY) || 248,
    visualLayers: clone(source.visualLayers || defaultPlayVisualLayers()),
    props: clone(source.props || []),
    dialogue: clone(source.dialogue || defaultDialogueState()),
    ui: clone(source.ui || defaultPlayUiMod()),
    audio: normalizePlayAudioRecord(source.audio || { assetId: "", name: "", dataUrl: "", volume: 0.7, loop: true })
  };
}
function captureActivePlayScene() {
  const pm = state?.playMode;
  if (!pm || !Array.isArray(pm.scenes) || !pm.scenes.length) return;
  const index = pm.scenes.findIndex(scene => scene.id === pm.activeSceneId);
  if (index < 0) return;
  const current = pm.scenes[index];
  pm.scenes[index] = playSceneSnapshot(pm, current.id, current.name);
}
function applyPlayScene(scene) {
  const pm = state.playMode;
  if (!scene || !pm) return;
  ["idleFrame", "walkFrame", "jumpFrame", "sceneWidth", "sceneHeight", "worldWidth", "groundY", "actorScale", "backgroundFrame", "backgroundScale", "showGridOverlay", "cameraFollow", "autoScroll", "scrollSpeed", "sceneryFrame", "sceneryScale", "scenerySpeed", "sceneryY"].forEach(key => { pm[key] = clone(scene[key]); });
  pm.visualLayers = clone(scene.visualLayers || defaultPlayVisualLayers());
  pm.props = clone(scene.props || []);
  pm.dialogue = clone(scene.dialogue || defaultDialogueState());
  pm.ui = clone(scene.ui || defaultPlayUiMod());
  pm.audio = normalizePlayAudioRecord(scene.audio || { assetId: "", name: "", dataUrl: "", volume: 0.7, loop: true });
  pm.activeSceneId = scene.id;
}

function stopPlayAudio() {
  if (!playAudioElement) return;
  playAudioElement.pause();
  playAudioElement.removeAttribute("src");
  playAudioElement.load();
  playAudioElement = null;
}
function syncPlayAudio(shouldPlay = playRunning) {
  const audio = resolvedPlayAudio();
  if (!shouldPlay || !audio?.dataUrl || playAudioMixerVolume("music") <= 0) { stopPlayAudio(); return; }
  if (!playAudioElement || playAudioElement.dataset.sceneId !== state.playMode.activeSceneId || playAudioElement.dataset.assetId !== String(audio.assetId || "") || playAudioElement.src !== audio.dataUrl) {
    stopPlayAudio();
    playAudioElement = new Audio(audio.dataUrl);
    playAudioElement.dataset.sceneId = state.playMode.activeSceneId;
    playAudioElement.dataset.assetId = String(audio.assetId || "");
  }
  playAudioElement.loop = audio.loop !== false;
  playAudioElement.volume = Math.max(0, Math.min(Number(audio.volume) || 0, 1)) * playAudioMixerVolume("music");
  playAudioElement.play().catch(() => setStatus("Scene audio is ready after the next interaction."));
}
function uniquePlaySceneId(name = "scene") {
  const base = playSceneId(name);
  let id = base;
  let index = 2;
  while (state.playMode.scenes.some(scene => scene.id === id)) id = `${base}-${index++}`;
  return id;
}
function renderPlaySceneManager() {
  const scenes = state.playMode.scenes || [];
  if (playSceneSelect) {
    playSceneSelect.innerHTML = "";
    scenes.forEach(scene => {
      const option = document.createElement("option");
      option.value = scene.id;
      option.textContent = scene.name;
      playSceneSelect.appendChild(option);
    });
    playSceneSelect.value = state.playMode.activeSceneId;
  }
  const active = scenes.find(scene => scene.id === state.playMode.activeSceneId) || scenes[0];
  if (playSceneNameInput) playSceneNameInput.value = active?.name || "Scene";
  if (playSceneDeleteBtn) playSceneDeleteBtn.disabled = scenes.length <= 1;
  if (playAudioVolumeInput) playAudioVolumeInput.value = String(state.playMode.audio?.volume ?? 0.7);
  if (playAudioFileInput) playAudioFileInput.setAttribute("aria-label", state.playMode.audio?.name ? `Replace scene audio ${state.playMode.audio.name}` : "Choose scene audio");
  if (playInventoryList) {
    playInventoryList.innerHTML = "";
    (state.playMode.inventory || []).forEach((item, index) => {
      const row = document.createElement("div");
      row.className = "inventory-item";
      const label = document.createElement("span");
      label.textContent = item;
      const remove = document.createElement("button");
      remove.type = "button";
      remove.textContent = "Remove";
      remove.setAttribute("aria-label", `Remove ${item} from inventory`);
      remove.onclick = () => {
        pushHistory();
        state.playMode.inventory.splice(index, 1);
        renderPlaySceneManager();
        saveLocal();
      };
      row.append(label, remove);
      playInventoryList.appendChild(row);
    });
  }
  const targetValue = playPropTargetSceneSelect?.value || state.playMode.props[selectedPlayProp]?.targetSceneId || "";
  if (playPropTargetSceneSelect) {
    playPropTargetSceneSelect.innerHTML = '<option value="">No transition</option>';
    scenes.filter(scene => scene.id !== state.playMode.activeSceneId).forEach(scene => {
      const option = document.createElement("option");
      option.value = scene.id;
      option.textContent = scene.name;
      playPropTargetSceneSelect.appendChild(option);
    });
    playPropTargetSceneSelect.value = Array.from(playPropTargetSceneSelect.options).some(option => option.value === targetValue) ? targetValue : "";
  }
  const prefabValue = playPropPrefabSelect?.value || state.playMode.props[selectedPlayProp]?.prefabId || "";
  if (playPropPrefabSelect) {
    playPropPrefabSelect.innerHTML = '<option value="">No prefab</option>';
    (state.playMode.prefabs || []).forEach(prefab => {
      const option = document.createElement("option");
      option.value = prefab.id;
      option.textContent = prefab.name;
      playPropPrefabSelect.appendChild(option);
    });
    playPropPrefabSelect.value = Array.from(playPropPrefabSelect.options).some(option => option.value === prefabValue) ? prefabValue : "";
  }
  window.PixelBugAudioStudio?.render?.();
}
function switchPlayScene(sceneId, runtime = false) {
  const target = state.playMode.scenes.find(scene => scene.id === sceneId);
  if (!target || target.id === state.playMode.activeSceneId) return false;
  captureActivePlayScene();
  applyPlayScene(target);
  normalizeProject();
  selectedPlayProp = -1;
  selectedPlayLayer = 0;
  playDialogueActive = false;
  activeDialogueSourceId = "";
  resetPlayActor(false);
  renderPlayPanel();
  syncPlayAudio(playRunning);
  if (runtime) window.PixelBugNodeEditor?.runEvent?.("sceneStart", { sceneId: target.id, sceneName: target.name });
  saveLocal();
  setStatus(`Scene changed to ${target.name}.`);
  return true;
}
function addPlayScene(duplicate = false) {
  pushHistory();
  captureActivePlayScene();
  const current = state.playMode.scenes.find(scene => scene.id === state.playMode.activeSceneId);
  const name = `Scene ${state.playMode.scenes.length + 1}`;
  const id = uniquePlaySceneId(name);
  const source = duplicate && current ? current : playSceneSnapshot({}, id, name);
  const scene = playSceneSnapshot(source, id, duplicate && current ? `${current.name} Copy` : name);
  state.playMode.scenes.push(scene);
  applyPlayScene(scene);
  normalizeProject();
  selectedPlayProp = -1;
  resetPlayActor(false);
  renderPlayPanel();
  saveLocal();
  setStatus(duplicate ? "Scene duplicated." : "Scene added.");
}
function deleteActivePlayScene() {
  if (state.playMode.scenes.length <= 1) return;
  pushHistory();
  const index = state.playMode.scenes.findIndex(scene => scene.id === state.playMode.activeSceneId);
  state.playMode.scenes.splice(Math.max(0, index), 1);
  const next = state.playMode.scenes[Math.max(0, Math.min(index, state.playMode.scenes.length - 1))];
  state.playMode.scenes.forEach(scene => (scene.props || []).forEach(prop => { if (prop.targetSceneId === state.playMode.activeSceneId) prop.targetSceneId = ""; }));
  applyPlayScene(next);
  normalizeProject();
  selectedPlayProp = -1;
  resetPlayActor(false);
  renderPlayPanel();
  saveLocal();
  setStatus("Scene deleted.");
}
function renameActivePlayScene() {
  const scene = state.playMode.scenes.find(item => item.id === state.playMode.activeSceneId);
  if (!scene) return;
  scene.name = String(playSceneNameInput?.value || scene.name || "Scene").trim().slice(0, 40) || "Scene";
  captureActivePlayScene();
  renderPlaySceneManager();
  saveLocal();
}
function addInventoryItem() {
  const item = String(playInventoryInput?.value || "").trim().slice(0, 40);
  if (!item) return;
  if (!state.playMode.inventory.includes(item)) state.playMode.inventory.push(item);
  if (playInventoryInput) playInventoryInput.value = "";
  renderPlaySceneManager();
  saveLocal();
  setStatus("Inventory item added.");
}
function saveSelectedPlayPrefab() {
  const prop = state.playMode.props[selectedPlayProp];
  if (!prop) { setStatus("Select an object before saving a prefab."); return; }
  pushHistory();
  const id = `prefab-${Date.now().toString(36)}`;
  const prefab = { id, name: `Prefab ${state.playMode.prefabs.length + 1}`, prop: { ...clone(prop), x: 0, y: 0, prefabId: id } };
  state.playMode.prefabs.push(prefab);
  prop.prefabId = id;
  normalizeProject();
  renderPlaySceneManager();
  syncSelectedPlayPropControls();
  saveLocal();
  setStatus("Prefab saved.");
}
function loadSceneAudio(file) {
  if (!file) return;
  const allowed = /^(audio\/(mpeg|wav|ogg|webm|mp4|x-m4a))$/i.test(file.type) || /\.(mp3|wav|ogg|webm|m4a)$/i.test(file.name);
  if (!allowed || file.size > 12 * 1024 * 1024) { setStatus("Choose an MP3, WAV, OGG, WebM, or M4A file no larger than 12 MB."); return; }
  const reader = new FileReader();
  reader.onload = () => {
    const dataUrl = String(reader.result || "");
    const otherAudioChars = (state.playMode.scenes || []).filter(scene => scene.id !== state.playMode.activeSceneId).reduce((sum, scene) => sum + String(scene.audio?.dataUrl || "").length, 0);
    if (otherAudioChars + dataUrl.length > 64 * 1024 * 1024) { setStatus("Project audio storage is full. Keep embedded audio under 48 MB."); return; }
    pushHistory();
    state.playMode.audio = { name: String(file.name).slice(0, 80), dataUrl, volume: Math.max(0, Math.min(Number(playAudioVolumeInput?.value) || 0.7, 1)) };
    captureActivePlayScene();
    syncPlayAudio(playRunning);
    renderPlaySceneManager();
    saveLocal();
    setStatus("Scene audio loaded.");
  };
  reader.onerror = () => setStatus("Scene audio could not be read.");
  reader.readAsDataURL(file);
}
function readPlayGamepad() {
  const pads = navigator.getGamepads?.() || [];
  const pad = Array.from(pads).find(Boolean);
  if (!pad) return { left: false, right: false, jump: false, interact: false };
  return {
    left: Number(pad.axes?.[0] || 0) < -0.35 || pad.buttons?.[14]?.pressed === true,
    right: Number(pad.axes?.[0] || 0) > 0.35 || pad.buttons?.[15]?.pressed === true,
    jump: pad.buttons?.[0]?.pressed === true || pad.buttons?.[12]?.pressed === true,
    interact: pad.buttons?.[1]?.pressed === true || pad.buttons?.[2]?.pressed === true
  };
}

function defaultPlayUiMod() {
  return {
    dialogueBoxColor: "rgba(15,15,15,0.94)",
    dialogueInkColor: "#f7f0da",
    dialogueBorderColor: "#f7f0da",
    dialogueBorderWidth: 4,
    dialogueFont: "system-ui, sans-serif",
    dialogueNameSize: 16,
    dialogueTextSize: 15,
    dialogueMargin: 0.035,
    dialogueBoxHeight: 0.28,
    dialoguePortrait: true,
    dialogueCounter: true
  };
}
function clampNumber(value, fallback, min, max) {
  const next = Number(value);
  return Number.isFinite(next) ? Math.max(min, Math.min(next, max)) : fallback;
}
function cleanCssColor(value, fallback) {
  const text = String(value || "").trim();
  if (/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(text)) return text;
  if (/^rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*(?:0|1|0?\.\d+))?\s*\)$/i.test(text)) return text;
  return fallback;
}
function cleanFontFamily(value, fallback) {
  const text = String(value || "").trim();
  if (!text || text.length > 80 || /[;{}<>]/.test(text)) return fallback;
  return text;
}
function normalizePlayUiMod(input = {}) {
  const base = defaultPlayUiMod();
  return {
    dialogueBoxColor: cleanCssColor(input.dialogueBoxColor, base.dialogueBoxColor),
    dialogueInkColor: cleanCssColor(input.dialogueInkColor, base.dialogueInkColor),
    dialogueBorderColor: cleanCssColor(input.dialogueBorderColor, base.dialogueBorderColor),
    dialogueBorderWidth: clampNumber(input.dialogueBorderWidth, base.dialogueBorderWidth, 0, 16),
    dialogueFont: cleanFontFamily(input.dialogueFont, base.dialogueFont),
    dialogueNameSize: clampNumber(input.dialogueNameSize, base.dialogueNameSize, 8, 32),
    dialogueTextSize: clampNumber(input.dialogueTextSize, base.dialogueTextSize, 8, 30),
    dialogueMargin: clampNumber(input.dialogueMargin, base.dialogueMargin, 0.01, 0.12),
    dialogueBoxHeight: clampNumber(input.dialogueBoxHeight, base.dialogueBoxHeight, 0.18, 0.55),
    dialoguePortrait: input.dialoguePortrait !== false,
    dialogueCounter: input.dialogueCounter !== false
  };
}
function parsePlayUiModCode(code) {
  const text = String(code || "").trim();
  if (!text) return defaultPlayUiMod();
  if (text.length > 6000) throw new Error("Play UI settings too long.");
  const parsed = JSON.parse(text);
  window.PixelBugProjectGuard.inspect(parsed, { maxDepth: 12, maxValues: 256, maxStringChars: 6000 });
  return normalizePlayUiMod(parsed);
}
function playUiMod() {
  return normalizePlayUiMod(state.playMode?.ui || {});
}
function stringifyPlayUiMod(ui = state.playMode?.ui) {
  return JSON.stringify(normalizePlayUiMod(ui || {}), null, 2);
}


function voxelSliceMaxForDimensions(plane, width, height, depth) {
  return plane === "xy" ? depth - 1 : plane === "xz" ? height - 1 : width - 1;
}

function defaultVoxelOrigin(width = 32, height = 32, depth = 32) {
  return {
    x: Math.max(0, Math.min(Math.floor((Number(width) || 32) / 2), Math.max(0, (Number(width) || 32) - 1))),
    y: Math.max(0, Math.min(Math.floor((Number(height) || 32) / 2), Math.max(0, (Number(height) || 32) - 1))),
    z: Math.max(0, Math.min(Math.floor((Number(depth) || 32) / 2), Math.max(0, (Number(depth) || 32) - 1)))
  };
}

function normalizeVoxelOrigin(input = {}, width = 32, height = 32, depth = 32) {
  const fallback = defaultVoxelOrigin(width, height, depth);
  const x = Math.round(Number(input?.x));
  const y = Math.round(Number(input?.y));
  const z = Math.round(Number(input?.z));
  return {
    x: Math.max(0, Math.min(Number.isInteger(x) ? x : fallback.x, Math.max(0, width - 1))),
    y: Math.max(0, Math.min(Number.isInteger(y) ? y : fallback.y, Math.max(0, height - 1))),
    z: Math.max(0, Math.min(Number.isInteger(z) ? z : fallback.z, Math.max(0, depth - 1)))
  };
}

function defaultVoxelViewCanvas(viewYaw = 0, width = 32, height = 32, depth = 32, origin = defaultVoxelOrigin(width, height, depth)) {
  const view = ((Math.round(Number(viewYaw) || 0) % VOXEL_MODE_VIEW_LABELS.length) + VOXEL_MODE_VIEW_LABELS.length) % VOXEL_MODE_VIEW_LABELS.length;
  const anchor = normalizeVoxelOrigin(origin, width, height, depth);
  if (view === 1) return { viewYaw: view, name: "Right", plane: "yz", slice: anchor.x };
  if (view === 2) return { viewYaw: view, name: "Back", plane: "xy", slice: anchor.z };
  if (view === 3) return { viewYaw: view, name: "Left", plane: "yz", slice: anchor.x };
  if (view === 4) return { viewYaw: view, name: "Top", plane: "xz", slice: anchor.y };
  if (view === 5) return { viewYaw: view, name: "Bottom", plane: "xz", slice: anchor.y };
  return { viewYaw: 0, name: "Front", plane: "xy", slice: anchor.z };
}

function defaultVoxelViewCanvases(width = 32, height = 32, depth = 32, origin = defaultVoxelOrigin(width, height, depth)) {
  return VOXEL_MODE_VIEW_LABELS.map((_label, index) => defaultVoxelViewCanvas(index, width, height, depth, origin));
}

function normalizeVoxelViewCanvas(input = {}, viewYaw = 0, width = 32, height = 32, depth = 32, origin = defaultVoxelOrigin(width, height, depth)) {
  const view = ((Math.round(Number(input.viewYaw ?? viewYaw) || 0) % VOXEL_MODE_VIEW_LABELS.length) + VOXEL_MODE_VIEW_LABELS.length) % VOXEL_MODE_VIEW_LABELS.length;
  const fallback = defaultVoxelViewCanvas(view, width, height, depth, origin);
  const plane = ["xy", "xz", "yz"].includes(input.plane) ? input.plane : fallback.plane;
  const sliceMax = voxelSliceMaxForDimensions(plane, width, height, depth);
  const slice = Math.max(0, Math.min(Math.round(Number(input.slice ?? fallback.slice) || 0), sliceMax));
  return { viewYaw: view, name: fallback.name, plane, slice };
}

// Rig helpers
function voxelModeCleanPartId(value = "") {
  return String(value || "").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40);
}
function voxelModeCleanPartName(value = "", fallback = "Part") {
  return String(value || fallback).replace(/[\u0000-\u001f<>:"/\\|?*]/g, "").trim().slice(0, 32) || fallback;
}
function voxelModeVector(input = {}, fallback = {}, minimum = -Infinity, maximum = Infinity) {
  const read = axis => Math.max(minimum, Math.min(Number.isFinite(Number(input?.[axis])) ? Number(input[axis]) : Number(fallback?.[axis]) || 0, maximum));
  return { x: read("x"), y: read("y"), z: read("z") };
}
function defaultVoxelParts(width = 32, height = 32, depth = 32, origin = defaultVoxelOrigin(width, height, depth)) {
  const pivot = voxelModeVector(origin, defaultVoxelOrigin(width, height, depth), 0, Math.max(width, height, depth));
  return [{ id: "part-root", name: "Root", parentId: "", pivot, translation: { x: 0, y: 0, z: 0 }, rotation: { x: 0, y: 0, z: 0 }, scale: { x: 1, y: 1, z: 1 }, visible: true, locked: false, opacity: 1 }];
}
function normalizeVoxelParts(input = [], width = 32, height = 32, depth = 32, origin = defaultVoxelOrigin(width, height, depth)) {
  const source = Array.isArray(input) && input.length ? input : defaultVoxelParts(width, height, depth, origin);
  const used = new Set();
  const parts = source.slice(0, 64).map((item, index) => {
    let id = voxelModeCleanPartId(item?.id) || (index === 0 ? "part-root" : `part-${index + 1}`);
    if (used.has(id)) {
      let suffix = 2;
      while (used.has(`${id}-${suffix}`)) suffix++;
      id = `${id}-${suffix}`;
    }
    used.add(id);
    const pivot = voxelModeVector(item?.pivot, index === 0 ? origin : origin, 0, Math.max(width, height, depth));
    const translation = voxelModeVector(item?.translation, {}, -96, 96);
    const rotation = voxelModeVector(item?.rotation, {}, -360, 360);
    const scale = voxelModeVector(item?.scale, { x: 1, y: 1, z: 1 }, 0.1, 8);
    return { id, name: voxelModeCleanPartName(item?.name, index === 0 ? "Root" : `Part ${index + 1}`), parentId: voxelModeCleanPartId(item?.parentId), pivot, translation, rotation, scale, visible: item?.visible !== false, locked: item?.locked === true, opacity: Math.max(0.1, Math.min(Number(item?.opacity) || 1, 1)) };
  });
  if (!parts.length) return defaultVoxelParts(width, height, depth, origin);
  const ids = new Set(parts.map(part => part.id));
  parts[0].parentId = "";
  parts.forEach((part, index) => {
    if (!ids.has(part.parentId) || part.parentId === part.id || index === 0) part.parentId = "";
    const seen = new Set([part.id]);
    let parentId = part.parentId;
    while (parentId) {
      if (seen.has(parentId)) { part.parentId = ""; break; }
      seen.add(parentId);
      parentId = parts.find(item => item.id === parentId)?.parentId || "";
    }
  });
  return parts;
}


// Armature schema
function voxelModeCleanArmatureId(value = "", fallback = "item") {
  return voxelModeCleanPartId(value) || fallback;
}
function voxelModeSourceId(value = "") {
  const clean = String(value || "").replace(/[^a-zA-Z0-9_-]+/g, "").slice(0, 64);
  return clean || `pb-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}
function voxelModeRootTail(part, children, width, height, depth) {
  const child = children[0];
  let dx = child ? child.pivot.x - part.pivot.x : 0;
  let dy = child ? child.pivot.y - part.pivot.y : 1;
  let dz = child ? child.pivot.z - part.pivot.z : 0;
  const distance = Math.hypot(dx, dy, dz);
  if (distance < 0.001) { dx = 0; dy = 1; dz = 0; }
  const length = Math.max(1, Math.min(distance || 1, 4));
  const divisor = Math.hypot(dx, dy, dz) || 1;
  return {
    x: Math.max(-1, Math.min(part.pivot.x + dx / divisor * length, width + 1)),
    y: Math.max(-1, Math.min(part.pivot.y + dy / divisor * length, height + 1)),
    z: Math.max(-1, Math.min(part.pivot.z + dz / divisor * length, depth + 1))
  };
}
function normalizeVoxelArmature(input = {}, parts = [], width = 32, height = 32, depth = 32, activePartId = "") {
  const sourceBones = Array.isArray(input?.bones) ? input.bones : [];
  const sourceJoints = Array.isArray(input?.joints) ? input.joints : [];
  const oldBoneByPart = new Map(sourceBones.map(bone => [voxelModeCleanPartId(bone?.partId), bone]));
  const oldJointById = new Map(sourceJoints.map(joint => [voxelModeCleanArmatureId(joint?.id, ""), joint]).filter(([id]) => id));
  const usedBoneIds = new Set();
  const boneIdByPart = new Map();
  parts.forEach((part, index) => {
    const old = oldBoneByPart.get(part.id);
    let id = voxelModeCleanArmatureId(old?.id, `bone-${part.id}`);
    if (usedBoneIds.has(id)) {
      let suffix = 2;
      while (usedBoneIds.has(`${id}-${suffix}`)) suffix++;
      id = `${id}-${suffix}`;
    }
    usedBoneIds.add(id);
    boneIdByPart.set(part.id, id);
  });
  const joints = [];
  const addJoint = (id, position, preserve = false) => {
    const old = oldJointById.get(id);
    const fallback = preserve && old?.position ? old.position : position;
    const joint = { id, position: voxelModeVector(fallback, position, -1, Math.max(width, height, depth) + 1) };
    joints.push(joint);
    return joint;
  };
  parts.forEach(part => addJoint(`joint-${part.id}`, part.pivot));
  parts.filter(part => !part.parentId).forEach(part => {
    const children = parts.filter(item => item.parentId === part.id);
    addJoint(`joint-${part.id}-tip`, voxelModeRootTail(part, children, width, height, depth), true);
  });
  const bones = parts.map((part, index) => {
    const old = oldBoneByPart.get(part.id) || {};
    const root = !part.parentId;
    const headJointId = root ? `joint-${part.id}` : `joint-${part.parentId}`;
    const tailJointId = root ? `joint-${part.id}-tip` : `joint-${part.id}`;
    const parentBoneId = boneIdByPart.get(part.parentId) || "";
    const parentPart = parts.find(item => item.id === part.parentId);
    const parentRoot = parentPart ? !parentPart.parentId : false;
    return {
      id: boneIdByPart.get(part.id),
      name: voxelModeCleanPartName(part.name, index ? `Bone ${index + 1}` : "Root"),
      partId: part.id,
      parentBoneId,
      headJointId,
      tailJointId,
      roll: Math.max(-360, Math.min(Number(old.roll) || 0, 360)),
      deform: old.deform !== false,
      bindRadius: Math.max(0.25, Math.min(Number(old.bindRadius) || 1.5, 12)),
      connected: Boolean(parentBoneId && !parentRoot)
    };
  });
  const boneIds = new Set(bones.map(bone => bone.id));
  const jointIds = new Set(joints.map(joint => joint.id));
  const fallbackBone = bones.find(bone => bone.partId === activePartId) || bones[0];
  const requested = voxelModeCleanArmatureId(input?.activeBoneId, "");
  const activeBoneId = boneIds.has(requested) ? requested : fallbackBone?.id || "";
  const activeBone = bones.find(bone => bone.id === activeBoneId) || bones[0];
  const requestedJoint = voxelModeCleanArmatureId(input?.activeJointId, "");
  return {
    version: 3,
    name: voxelModeCleanPartName(input?.name, "Voxel Armature"),
    joints,
    bones,
    activeBoneId,
    activeJointId: jointIds.has(requestedJoint) ? requestedJoint : activeBone?.tailJointId || activeBone?.headJointId || ""
  };
}

function normalizeVoxelModeClip(input = {}, width = 1, height = 1, depth = 1) {
  const source = Array.isArray(input.cubes) ? input.cubes : [];
  const seen = new Map();
  source.slice(0, MAX_VOXEL_MODE_CUBES).forEach(cube => {
    const x = Math.round(Number(cube?.x));
    const y = Math.round(Number(cube?.y));
    const z = Math.round(Number(cube?.z));
    const cubeColor = String(cube?.color || "").toLowerCase();
    if (!Number.isInteger(x) || !Number.isInteger(y) || !Number.isInteger(z)) return;
    if (x < 0 || y < 0 || z < 0 || x >= width || y >= height || z >= depth) return;
    if (!isHexColor(cubeColor)) return;
    const material = VOXEL_MODE_MATERIALS.includes(cube?.material) ? cube.material : "matte";
    seen.set(`${x},${y},${z}`, { x, y, z, color: cubeColor, material, partId: voxelModeCleanPartId(cube?.partId) || "part-root", boneId: voxelModeCleanArmatureId(cube?.boneId, "") });
  });
  return Array.from(seen.values()).sort((a, b) => a.z - b.z || a.y - b.y || a.x - b.x);
}

function normalizeVoxelModeStamp(input = {}, index = 0) {
  const width = Math.max(1, Math.min(Math.round(Number(input.width) || 1), MAX_VOXEL_MODE_CANVAS_DIMENSION));
  const height = Math.max(1, Math.min(Math.round(Number(input.height) || 1), MAX_VOXEL_MODE_CANVAS_DIMENSION));
  const depth = Math.max(1, Math.min(Math.round(Number(input.depth) || 1), MAX_VOXEL_MODE_DEPTH));
  const cubes = normalizeVoxelModeClip(input, width, height, depth);
  if (!cubes.length) return null;
  const name = String(input.name || `Stamp ${index + 1}`).replace(/[\u0000-\u001f<>:"\/\\|?*]/g, "").trim().slice(0, 28) || `Stamp ${index + 1}`;
  return { id: String(input.id || `stamp-${Date.now()}-${index}`), name, width, height, depth, cubes };
}

// Pose snapshots
function normalizeVoxelModePoseSnapshot(input = null, parts = []) {
  if (!input || typeof input !== "object") return null;
  const partIds = new Set(parts.map(part => part.id));
  const source = Array.isArray(input) ? input.map(item => [voxelModeCleanPartId(item?.partId), item]) : Object.entries(input);
  const poses = {};
  source.forEach(([rawId, item]) => {
    const partId = voxelModeCleanPartId(rawId || item?.partId);
    if (!partIds.has(partId) || !item || typeof item !== "object") return;
    poses[partId] = {
      translation: voxelModeVector(item.translation, {}, -96, 96),
      rotation: voxelModeVector(item.rotation, {}, -360, 360),
      scale: voxelModeVector(item.scale, { x: 1, y: 1, z: 1 }, 0.1, 8)
    };
  });
  return poses;
}
