function formatRecoveryDate(value) {
  const date = new Date(Number(value) || 0);
  return Number.isNaN(date.getTime()) ? "Unknown time" : date.toLocaleString();
}

async function renderRecoverySnapshots() {
  if (!recoverySnapshotList || !recoverySnapshotStatus) return;
  recoverySnapshotList.innerHTML = "";
  recoverySnapshotStatus.textContent = "Loading recovery snapshots.";
  try {
    const snapshots = await window.pixelBug.listRecoverySnapshots();
    if (!snapshots.length) {
      const empty = document.createElement("p");
      empty.className = "modal-note";
      empty.textContent = "No rotating recovery snapshots are available yet.";
      recoverySnapshotList.appendChild(empty);
      recoverySnapshotStatus.textContent = "No recovery snapshots.";
      return;
    }
    snapshots.forEach(snapshot => {
      const row = document.createElement("article");
      row.className = "recovery-snapshot-row";
      const image = document.createElement("img");
      image.alt = "";
      image.src = snapshot.summary?.thumbnail || "data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=";
      const copy = document.createElement("div");
      copy.className = "recovery-snapshot-copy";
      const strong = document.createElement("strong");
      strong.textContent = snapshot.summary?.name || "Recovery Snapshot";
      const date = document.createElement("small");
      date.textContent = formatRecoveryDate(snapshot.savedAt);
      const details = document.createElement("small");
      const tabs = Math.max(1, Number(snapshot.summary?.tabCount) || 1);
      const dirty = Math.max(0, Number(snapshot.summary?.dirtyCount) || 0);
      details.textContent = `${tabs} tab${tabs === 1 ? "" : "s"} · ${dirty} unsaved · ${ProjectHealth.formatBytes(snapshot.bytes)}`;
      copy.append(strong, date, details);
      const actions = document.createElement("div");
      actions.className = "recovery-snapshot-actions";
      const restore = document.createElement("button");
      restore.type = "button";
      restore.textContent = "Restore";
      restore.setAttribute("aria-label", `Restore ${strong.textContent} from ${date.textContent}`);
      restore.onclick = async () => {
        if (!window.confirm("Replace the open project tabs with this recovery snapshot?")) return;
        recoverySnapshotStatus.textContent = "Loading recovery snapshot.";
        try {
          const result = await window.pixelBug.loadRecoverySnapshot(snapshot.id);
          const restored = await documentWorkflowController?.restoreRecoveryText?.(result.payload);
          recoverySnapshotStatus.textContent = restored ? "Recovery snapshot restored." : "Recovery snapshot could not be restored.";
          if (restored) saveLocalNow();
        } catch (error) {
          recoverySnapshotStatus.textContent = error?.message || "Recovery snapshot could not be restored.";
        }
      };
      const remove = document.createElement("button");
      remove.type = "button";
      remove.textContent = "Delete";
      remove.setAttribute("aria-label", `Delete ${strong.textContent} recovery snapshot`);
      remove.onclick = async () => {
        if (!window.confirm("Delete this recovery snapshot?")) return;
        await window.pixelBug.deleteRecoverySnapshot(snapshot.id);
        await renderRecoverySnapshots();
      };
      actions.append(restore, remove);
      row.append(image, copy, actions);
      recoverySnapshotList.appendChild(row);
    });
    recoverySnapshotStatus.textContent = `${snapshots.length} recovery snapshot${snapshots.length === 1 ? "" : "s"}.`;
  } catch (error) {
    recoverySnapshotStatus.textContent = error?.message || "Recovery snapshots could not be loaded.";
  }
}

async function createRecoverySnapshot() {
  if (!window.PixelBugDocuments?.serializeRecovery) return;
  if (recoverySnapshotStatus) recoverySnapshotStatus.textContent = "Creating recovery snapshot.";
  try {
    const payload = window.PixelBugDocuments.serializeRecovery();
    await window.pixelBug.saveRecovery({ payload, summary: window.PixelBugDocuments.recoverySummary?.(), forceSnapshot: true });
    await renderRecoverySnapshots();
    setStatus("Recovery snapshot created.");
  } catch (error) {
    if (recoverySnapshotStatus) recoverySnapshotStatus.textContent = error?.message || "Recovery snapshot could not be created.";
  }
}

function renderProjectHealth() {
  if (!projectHealthGrid || !projectHealthWarnings) return;
  const health = ProjectHealth.inspect(state, { undoStack, redoStack, stringify: project => ProjectPackage.stringify(project) });
  const records = [
    ["Canvas", `${health.width} × ${health.height}`],
    ["Frames", String(health.frames)],
    ["Layers", `${health.layers} total · ${health.visibleLayers} visible`],
    ["Pixel cells", health.pixelCells.toLocaleString()],
    ["Embedded audio", `${health.audioAssets} asset${health.audioAssets === 1 ? "" : "s"} · ${ProjectHealth.formatBytes(health.embeddedAudioBytes)}`],
    ["Undo memory", ProjectHealth.formatBytes(health.undoBytes + health.redoBytes)],
    ["Saved project", ProjectHealth.formatBytes(health.projectBytes)]
  ];
  projectHealthGrid.innerHTML = "";
  records.forEach(([label, value]) => {
    const term = document.createElement("dt");
    term.textContent = label;
    const detail = document.createElement("dd");
    detail.textContent = value;
    projectHealthGrid.append(term, detail);
  });
  projectHealthWarnings.innerHTML = "";
  if (!health.warnings.length) {
    const ok = document.createElement("p");
    ok.className = "project-health-ok";
    ok.textContent = "No project limit warnings were detected.";
    projectHealthWarnings.appendChild(ok);
  } else health.warnings.forEach(message => {
    const warning = document.createElement("p");
    warning.className = "project-health-warning";
    warning.textContent = message;
    projectHealthWarnings.appendChild(warning);
  });
  if (projectHealthStatus) projectHealthStatus.textContent = `Project health updated with ${health.warnings.length} warning${health.warnings.length === 1 ? "" : "s"}.`;
}

