    playCtx.drawImage(propMetrics.canvas, propMetrics.sx, propMetrics.sy, propMetrics.sw, propMetrics.sh, px, Math.round(prop.y), propW, propH);
    playCtx.globalAlpha = 1;
    playCtx.strokeStyle = index === selectedPlayProp ? canvasInkColor() : prop.solid === false || open ? "#aaa" : canvasMutedColor();
    playCtx.lineWidth = index === selectedPlayProp ? 4 : 2;
    playCtx.setLineDash(prop.solid === false || open ? [6, 4] : []);
    playCtx.strokeRect(px, Math.round(prop.y), propW, propH);
    playCtx.setLineDash([]);
    if (open || prop.solid !== false) {
      playCtx.fillStyle = canvasInkColor();
      playCtx.font = "900 10px system-ui, sans-serif";
      playCtx.fillText(open ? "OPEN" : "SOLID", px + 4, Math.round(prop.y) + 12);
    }
