    const chunkKey = voxelModeChunkKey(cube.x, cube.y, cube.z);
    if (!voxelModeChunkIndex.has(chunkKey)) voxelModeChunkIndex.set(chunkKey, new Set());
    voxelModeChunkIndex.get(chunkKey).add(voxelModeKey(cube.x, cube.y, cube.z));
