      const partId = partIds.has(cube.partId) ? cube.partId : fallbackPartId;
      const boneId = boneIds.has(cube.boneId) ? cube.boneId : boneByPart.get(partId) || fallbackBoneId;
      cube.material = VOXEL_MODE_MATERIALS.includes(cube.material) ? cube.material : "matte";
      cube.partId = partId;
      cube.boneId = boneId;
      voxelModeCubeMap.set(voxelModeKey(cube.x, cube.y, cube.z), cube);
