    name,
    width: dims.width,
    height: dims.height,
    depth: dims.depth,
    cubes: cubes.map(cube => ({ x: cube.x - box.minX, y: cube.y - box.minY, z: cube.z - box.minZ, color: cube.color, material: cube.material || "matte", partId: cube.partId || voxelModeParts()[0].id }))
