    voxelModePreviewCtx.moveTo(origin.x, origin.y);
    voxelModePreviewCtx.lineTo(end.x, end.y);
    voxelModePreviewCtx.stroke();
    voxelModePreviewCtx.fillRect(end.x - radius, end.y - radius, radius * 2, radius * 2);
    voxelModePreviewCtx.fillStyle = "#ffffff";
    voxelModePreviewCtx.font = `900 ${Math.max(10, radius * 1.25)}px system-ui, sans-serif`;
    voxelModePreviewCtx.textAlign = "center";
    voxelModePreviewCtx.textBaseline = "middle";
    voxelModePreviewCtx.fillText(item.axis.toUpperCase(), end.x, end.y);
