    voxelModePreviewCtx.moveTo(start.x, start.y);
    voxelModePreviewCtx.lineTo(end.x, end.y);
    voxelModePreviewCtx.stroke();
    voxelModePreviewCtx.beginPath();
    voxelModePreviewCtx.arc(end.x, end.y, Math.max(5, transform.scale * 2.2), 0, Math.PI * 2);
    voxelModePreviewCtx.fill();
