    if (useWebGL && options.transparent !== true) {
      voxelModePreviewCtx.fillStyle = canvasBackgroundColor();
      voxelModePreviewCtx.fillRect(0, 0, voxelModePreviewCanvas.width, voxelModePreviewCanvas.height);
      if (options.hideGuides !== true) drawVoxelModeActivePlane(voxelModePreviewPlane);
    }
    if (!options.animationPreview && !options.exporting) drawVoxelModeAnimationOnionPreview(transform, model, angle, yaw, pitch);
