  if (printPreviewDragMode === "layer") announcePrintLayer(`${printLayerName(activePrintLayerId)} moved to X ${Math.round(printLayerState[activePrintLayerId].x)} and Y ${Math.round(printLayerState[activePrintLayerId].y)}.`);
  if (printPreviewDragMode === "resize") announcePrintLayer(`${printLayerName(activePrintLayerId)} resized to ${Math.round(printLayerState[activePrintLayerId].scale * 100)} percent.`);
  printLayerResizeCorner = -1;
