  playClearPropsBtn.onclick = () => { pushHistory(); state.playMode.props = []; selectedPlayProp = -1; renderPlayPanel(); drawPlayScene(); saveLocal(); setStatus("Play Mode scene cleared."); };
  if (playSceneSelect) playSceneSelect.onchange = () => switchPlayScene(playSceneSelect.value);
  if (playSceneNameInput) playSceneNameInput.onchange = renameActivePlayScene;
  if (playSceneAddBtn) playSceneAddBtn.onclick = () => addPlayScene(false);
