function projectMetaLabel(project = state) {
  const width = projectWidth(project);
  const height = projectHeight(project);
  const frames = Array.isArray(project.frames) ? project.frames.length : 1;
  const layers = Array.isArray(project.frames?.[0]?.layers) ? project.frames[0].layers.length : 1;
  return `${width} × ${height} · ${frames} frame${frames === 1 ? "" : "s"} · ${layers} layer${layers === 1 ? "" : "s"}`;
}

function ensureProjectId(project = state) {
  if (!project.projectId) project.projectId = `project-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  return project.projectId;
}

function thumbnailPixelsForProject(project = state) {
  const width = projectWidth(project);
  const height = projectHeight(project);
  const pixels = blankPixels(width, height);
  const safeFrame = Math.max(0, Math.min(Number(project.activeFrame) || 0, Math.max(0, (project.frames?.length || 1) - 1)));
  const projectFrame = project.frames?.[safeFrame] || project.frames?.[0];
  (projectFrame?.layers || []).forEach(projectLayer => {
    if (!projectLayer || projectLayer.visible === false || Number(projectLayer.opacity ?? 1) <= 0) return;
    const layerPixels = projectLayer.pixels || [];
    for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) if (layerPixels[y]?.[x]) pixels[y][x] = layerPixels[y][x];
  });
  return pixels;
}

function makeProjectThumbnail(project = state, targetSize = 96) {
  const width = projectWidth(project);
  const height = projectHeight(project);
  const thumb = document.createElement("canvas");
  thumb.width = targetSize;
  thumb.height = targetSize;
  const thumbCtx = thumb.getContext("2d", { alpha: false });
  thumbCtx.imageSmoothingEnabled = false;
  thumbCtx.fillStyle = canvasBackgroundColor();
  thumbCtx.fillRect(0, 0, targetSize, targetSize);
  const scale = Math.max(1, Math.floor(Math.min(targetSize / width, targetSize / height)));
  const offsetX = Math.floor((targetSize - width * scale) / 2);
  const offsetY = Math.floor((targetSize - height * scale) / 2);
  thumbnailPixelsForProject(project).forEach((row, y) => row.forEach((pixel, x) => {
    if (!pixel) return;
    thumbCtx.fillStyle = pixel;
    thumbCtx.fillRect(offsetX + x * scale, offsetY + y * scale, scale, scale);
  }));
  thumbCtx.strokeStyle = canvasInkColor();
  thumbCtx.lineWidth = 2;
  thumbCtx.strokeRect(offsetX, offsetY, width * scale, height * scale);
  return thumb.toDataURL("image/png");
}

function restoreStoredProject(project, message = "Project restored.") {
  let next;
  try {
    next = prepareProject(clone(project));
  } catch (_error) {
    setStatus("Stored project could not be opened.");
    return false;
  }
  pushHistory();
  state = next;
  ensureProjectId(state);
  normalizeProject();
  clampActive();
  syncControls();
  renderAll();
  saveLocal();
  window.PixelBugProjectGallery?.refresh?.();
  window.PixelBugSnapshots?.refresh?.();
  setStatus(message);
  return true;
}


